const SW_JS = "// Recipe Box service worker: keeps the app opening with no signal and shows timer alerts.\nconst VERSION = \"__VERSION__\";\nconst SHELL = \"rb-shell-\" + VERSION, DATA = \"rb-data\", PHOTOS = \"rb-photos\", FONTS = \"rb-fonts\";\n\nself.addEventListener(\"install\", e => {\n  e.waitUntil(caches.open(SHELL).then(c => c.addAll([\"/\", \"/manifest.webmanifest\", \"/icon-180.png\", \"/icon-512.png\"])).then(() => self.skipWaiting()));\n});\nself.addEventListener(\"activate\", e => {\n  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith(\"rb-shell-\") && k !== SHELL).map(k => caches.delete(k)))).then(() => self.clients.claim()));\n});\n\n// network first, saved copy when offline\nasync function networkFirst(req, cacheName) {\n  const cache = await caches.open(cacheName);\n  try {\n    const res = await fetch(req);\n    if (res.ok) cache.put(req, res.clone());\n    return res;\n  } catch {\n    const hit = await cache.match(req, { ignoreVary: true });\n    if (hit) { const h = new Headers(hit.headers); h.set(\"x-offline\", \"1\"); return new Response(hit.body, { status: hit.status, headers: h }); }\n    throw new Error(\"offline\");\n  }\n}\nasync function cacheFirst(req, cacheName) {\n  const cache = await caches.open(cacheName);\n  const hit = await cache.match(req);\n  if (hit) return hit;\n  const res = await fetch(req);\n  if (res.ok || res.type === \"opaque\") cache.put(req, res.clone());\n  return res;\n}\n\nself.addEventListener(\"fetch\", e => {\n  const req = e.request;\n  if (req.method !== \"GET\") return;\n  const url = new URL(req.url);\n  if (url.origin === location.origin) {\n    if (req.mode === \"navigate\") { e.respondWith(networkFirst(new Request(\"/\"), SHELL).catch(() => caches.match(\"/\"))); return; }\n    if (/^\\/api\\/(me|recipes|grocery|plan)(\\?|$)/.test(url.pathname + url.search.slice(0, 1))) { e.respondWith(networkFirst(req, DATA)); return; }\n    if (url.pathname.startsWith(\"/photo/\")) { e.respondWith(cacheFirst(req, PHOTOS)); return; }\n    return;\n  }\n  if (url.hostname === \"fonts.googleapis.com\" || url.hostname === \"fonts.gstatic.com\") e.respondWith(cacheFirst(req, FONTS));\n});\n\n// lock-screen timer alerts\nself.addEventListener(\"push\", e => {\n  let d = {}; try { d = e.data.json(); } catch { d = { title: \"Recipe Box\", body: e.data && e.data.text() }; }\n  e.waitUntil(self.registration.showNotification(d.title || \"Recipe Box\", {\n    body: d.body || \"\", tag: d.tag || \"recipe-box\", renotify: true, icon: \"/icon-180.png\", badge: \"/icon-180.png\", requireInteraction: true, data: { url: \"/\" }\n  }));\n});\nself.addEventListener(\"notificationclick\", e => {\n  e.notification.close();\n  e.waitUntil(self.clients.matchAll({ type: \"window\", includeUncontrolled: true }).then(list => {\n    for (const c of list) if (\"focus\" in c) return c.focus();\n    return self.clients.openWindow(\"/\");\n  }));\n});\n";
const PRIVACY_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Recipe Box Privacy</title>\n<style>\n:root{--bg:#ffffff;--ink:#2a1714;--muted:#6b5a56;--accent:#c2361e;color-scheme:light}\n@media (prefers-color-scheme: dark){:root{--bg:#1b1110;--ink:#fbeee9;--muted:#c4a59e;--accent:#ff8a72;color-scheme:dark}}\nbody{margin:0;background:var(--bg);color:var(--ink);font:17px/1.6 -apple-system,system-ui,\"Segoe UI\",sans-serif}\nmain{max-width:640px;margin:0 auto;padding:32px max(18px,env(safe-area-inset-left,0px)) 64px}\nh1{font-size:2rem;line-height:1.1;margin:0 0 4px}\nh2{font-size:1.15rem;margin:28px 0 6px}\np,li{color:var(--ink)}\n.muted{color:var(--muted)}\na{color:var(--accent)}\n</style>\n</head>\n<body>\n<main>\n<h1>Privacy</h1>\n<p class=\"muted\">Recipe Box at __HOST__</p>\n\n<h2>What we keep</h2>\n<p>Your name, email address, and a scrambled (hashed) version of your password. The recipes, grocery lists, meal plans, photos and stores your household adds. When something was added and by whom, so household members can see it.</p>\n\n<h2>Who can see it</h2>\n<p>Only the people in your household. Each household's recipes, lists and plans are kept separate from every other household. The person who runs this app can see household names, member counts and overall usage numbers so they can keep it running.</p>\n\n<h2>Recipe imports</h2>\n<p>When you import from a link, a caption or a screenshot, that text or image is sent to Cloudflare Workers AI to turn it into a recipe. It isn't used for anything else.</p>\n\n<h2>Timer alerts</h2>\n<p>If you turn on lock-screen alerts, your phone's notification address is stored so a timer can alert you. Turn alerts off in your phone's settings at any time.</p>\n\n<h2>Ads</h2>\n<p>If ads are shown, they are provided by Google AdSense, which may use cookies to show and measure ads. You can learn more and manage ad settings at <a href=\"https://policies.google.com/technologies/ads\">Google's ad policies page</a>.</p>\n\n<h2>Where it lives</h2>\n<p>Everything is stored on Cloudflare, which runs this app. Nothing is sold or shared with anyone else.</p>\n\n<h2>Deleting your data</h2>\n<p>You can delete recipes and list items in the app at any time. To delete your whole account, ask the person who invited you or the app's owner.</p>\n</main>\n</body>\n</html>\n";
